using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public sealed class RobotMotionCollision {public string A{get;set;}public string B{get;set;}public double[] Position{get;set;}public double Volume{get;set;}public Dictionary<string,double> Values{get;set;}}
 public sealed class RobotMotionReport {public string Status{get;set;}public int Visited{get;set;}public int CertifiedRegions{get;set;}public int UnresolvedRegions{get;set;}public double Seconds{get;set;}public string Scope{get;set;}public List<RobotMotionCollision> Collisions{get;set;}}
 public sealed partial class RobotDesignerForm {
  RobotMotionReport motionReport;bool motionBusy;readonly CADKernel motionKernel=new CADKernel();
  async void CheckCADMotion(){if(Build==null||!Build.Model.Valid||motionBusy||bodyBusy)return;Stop();var snapshot=Document.Clone();int ticket=revision;motionBusy=true;summary.Text="CAD-проверка диапазона: интервальные объёмы и точные пересечения…";try{var report=await Task.Factory.StartNew(()=>{var model=RobotCad.Build(snapshot);var parts=new List<object>();bool internalMotion=false;foreach(var e in model.Entries.Values.Where(x=>!x.Guide&&x.Category!="Крепёж"&&x.Category!="Проводка")){if(e.NativeMotion!=null){internalMotion=true;continue;}if(e.Part.MeshOverride!=null&&e.Part.NativeStep==null)throw new Exception("Для детали "+e.Part.Label+" есть только сетка: восстановите CAD-геометрию перед точной проверкой.");var step=CADNativeBridge.FromLegacyPart(e.Part).Features[0].Data;var mesh=e.Part.MeshOverride??PrintExport.Mesh(e.Part);var b=new[]{mesh.Points.Min(p=>p.X),mesh.Points.Min(p=>p.Y),mesh.Points.Min(p=>p.Z),mesh.Points.Max(p=>p.X),mesh.Points.Max(p=>p.Y),mesh.Points.Max(p=>p.Z)};parts.Add(new{Id=e.Id,Joint=e.JointId,Owner=e.OwnerId,InputSide=e.InputSide,Local=CADNativeBridge.Transform(e.Local),Bounds=b,Step=step});}var spec=new{Joints=snapshot.Ordered().Select(j=>new{Id=j.Id,Parent=j.ParentId,Offset=new[]{j.OffsetX,j.OffsetY,j.OffsetZ},End=new[]{j.EndX,j.EndY,j.EndZ},Mode=j.Mode==RobotJointMode.Неподвижный?"fixed":j.Linear?"linear":"rotate",Axis=j.Axis.X>0?0:j.Axis.Y>0?1:2,Minimum=j.Minimum,Maximum=j.Maximum,Position=j.Position}).ToArray(),Parts=parts,Budget=256,Seconds=30};var result=motionKernel.Run(new CADDocument(),"body_motion",null,null,null,new Dictionary<string,object>{{"Spec",spec}}).Motion;if(result==null)throw new Exception("Нет отчёта проверки движения.");if(internalMotion){result.Scope+=" Внутренняя кинематика пользовательских передач исключена: её нужно проверить отдельно.";if(result.Status=="clear")result.Status="unknown";}return result;});if(disposed)return;if(ticket!=revision){notes.AppendText("\r\nГеометрия или поза изменились во время проверки. Повторите проверку.");return;}motionReport=report;string state=report.Status=="collision"?"Найдено CAD-столкновение":report.Status=="clear"?"Разделение проверенных CAD-деталей подтверждено во всём диапазоне":"Отсутствие столкновений во всём диапазоне не подтверждено";summary.Text=state;summary.ForeColor=report.Status=="collision"?System.Drawing.Color.Firebrick:System.Drawing.Color.DarkGoldenrod;notes.AppendText("\r\n\r\n"+state+". Областей: "+report.Visited+", доказанно разделены "+report.CertifiedRegions+", неопределённых "+report.UnresolvedRegions+".\r\n"+report.Scope);foreach(var c in report.Collisions)notes.AppendText("\r\n"+c.A+" / "+c.B+": "+Engine.F(c.Volume)+" мм³. Кнопка «Показать столкновение» устанавливает найденную позу.");robotWeb.Send(new{type="issues",issues=report.Collisions.Select(c=>new{status="error",position=c.Position,partId=c.A,message="CAD-столкновение · "+c.B}).ToArray()});}catch(Exception ex){if(!disposed)notes.AppendText("\r\nCAD-проверка: "+ex.GetBaseException().Message);}finally{motionBusy=false;}}
  void ShowMotionCollision(){if(motionReport==null||motionReport.Collisions.Count==0){MessageBox.Show(this,"Сначала запустите CAD-проверку диапазона.");return;}var collision=motionReport.Collisions[0];if(Mutate(()=>{foreach(var pair in collision.Values){var joint=Document.Find(pair.Key);if(joint!=null)joint.Position=pair.Value;}})){RobotCadEntry entry;if(Build.Entries.TryGetValue(collision.A,out entry))Select(entry.JointId,entry.Id);robotWeb.Send(new{type="issues",issues=new[]{new{status="error",position=collision.Position,partId=collision.A,message="Пересечение · "+collision.B}}});}}
 }
}
